//! TCG and TCB validation against ERFA/SOFA reference values.
//!
//! The golden CSV is generated by `tools/gen_tcg_tcb_golden.py`, which
//! uses ERFA (through astropy's `tcg`/`tcb` scales). Neither WebGeocalc
//! nor CSPICE exposes these scales, so ERFA is the independent reference.
//!
//! TCG is a pure TT linear function and must match tightly. TCB is built
//! from this crate's IAU Fairhead & Bretagnon TDB model; the tolerance is
//! above the measured f64 spacing and far below the old NAIF model error.

use stkcraft_time::calendar::{gregorian_to_jdn, J2000_JDN};
use stkcraft_time::convert::tai_to_tt;
use stkcraft_time::coord::{tai_to_tcb, tai_to_tcg, tcb_to_tai, tcg_minus_tt, tcg_to_tai};
use stkcraft_time::{Epoch, LeapSecondTable};

fn tai_epoch(year: i32, month: u8, day: u8, hour: u8, minute: u8, second: f64) -> Epoch {
    let jdn = gregorian_to_jdn(year, month, day);
    let whole = second as i64;
    let frac = second - whole as f64;
    let sec = (jdn - J2000_JDN) * 86_400 + hour as i64 * 3_600 + minute as i64 * 60 + whole;
    Epoch::from_parts(sec, (frac * 1e9).round() as i64)
}

fn parse_tai(text: &str) -> Epoch {
    let (date, time) = text.split_once('T').expect("ISO date-time");
    let mut d = date.split('-');
    let year: i32 = d.next().unwrap().parse().unwrap();
    let month: u8 = d.next().unwrap().parse().unwrap();
    let day: u8 = d.next().unwrap().parse().unwrap();

    let mut t = time.split(':');
    let hour: u8 = t.next().unwrap().parse().unwrap();
    let minute: u8 = t.next().unwrap().parse().unwrap();
    let second: f64 = t.next().unwrap().parse().unwrap();

    tai_epoch(year, month, day, hour, minute, second)
}

#[test]
fn matches_erfa_golden() {
    let csv = include_str!("golden/tcg_tcb.csv");
    let lsk = LeapSecondTable::builtin().unwrap();

    let mut worst_tt: f64 = 0.0;
    let mut worst_tcg: f64 = 0.0;
    let mut worst_tcb: f64 = 0.0;
    let mut checked = 0;

    for line in csv.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with("tai,") {
            continue;
        }

        let fields: Vec<&str> = line.split(',').collect();
        let epoch = parse_tai(fields[0]);
        let tt: f64 = fields[1].parse().unwrap();
        let tcg: f64 = fields[3].parse().unwrap();
        let tcb: f64 = fields[4].parse().unwrap();

        worst_tt = worst_tt.max((tai_to_tt(epoch, &lsk) - tt).abs());
        worst_tcg = worst_tcg.max((tai_to_tcg(epoch, &lsk) - tcg).abs());
        worst_tcb = worst_tcb.max((tai_to_tcb(epoch, &lsk) - tcb).abs());
        checked += 1;
    }

    assert!(checked >= 5, "expected at least five golden rows");
    assert!(worst_tt < 1e-6, "TT mismatch {worst_tt:e} s");
    assert!(worst_tcg < 1e-6, "TCG mismatch {worst_tcg:e} s");
    // TCB uses the IAU TDB series, not the NAIF one-term model. The
    // measured error is about 2.4e-7 s; this threshold catches a regression
    // to the ~30 us NAIF model while allowing f64 spacing.
    assert!(worst_tcb < 1e-6, "TCB mismatch {worst_tcb:e} s");

    println!(
        "vs ERFA over {checked} epochs: TT {worst_tt:.3e} s, TCG {worst_tcg:.3e} s, TCB {worst_tcb:.3e} s"
    );
}

#[test]
fn tcg_offset_is_zero_at_the_iau_reference_epoch() {
    let lsk = LeapSecondTable::builtin().unwrap();
    // T0 = 1977-01-01T00:00:00 TAI.
    let epoch = tai_epoch(1977, 1, 1, 0, 0, 0.0);
    assert!(tcg_minus_tt(epoch, &lsk).abs() < 1e-9);
}

#[test]
fn tcg_and_tcb_round_trip() {
    let lsk = LeapSecondTable::builtin().unwrap();
    let epoch = tai_epoch(2016, 12, 31, 12, 0, 0.0);

    let tcg = tai_to_tcg(epoch, &lsk);
    let back_tcg = tcg_to_tai(tcg, &lsk);
    // TCG is returned as f64 seconds near 5.4e8, whose spacing is about
    // 60 ns; a sub-microsecond round trip is the floating-point limit.
    assert!((back_tcg.tai_seconds() - epoch.tai_seconds()).abs() < 1e-6);

    let tcb = tai_to_tcb(epoch, &lsk);
    let back_tcb = tcb_to_tai(tcb, &lsk);
    assert!((back_tcb.tai_seconds() - epoch.tai_seconds()).abs() < 1e-6);
}
